mkdir -p /tmp/adv && cat > /tmp/adv/model.py <<'PY'
import subprocess, sys, random, itertools
EXE='/workspace/dataset/test20_executable'

def toup(b):
    return b-32 if 0x61<=b<=0x7a else b

def cam_lower(s: bytes) -> bytes:
    out=bytearray(); cap=False
    for c in s:
        if c==0x5f: cap=True
        elif cap: out.append(toup(c)); cap=False
        else: out.append(c)
    return bytes(out)

def cam_upper(s: bytes) -> bytes:
    o=bytearray(cam_lower(s))
    if o: o[0]=toup(o[0])
    return bytes(o)

def run(b: bytes):
    p=subprocess.run([EXE,b],capture_output=True)
    if p.returncode!=0: return None,p.returncode
    lines=p.stdout.split(b'\n')
    return lines,0

def check(b: bytes):
    lines,rc=run(b)
    if lines is None: return ('ABORT',rc)
    if len(lines)<20: return ('SHORT',lines)
    l3=lines[2]; l4=lines[3]
    e3=cam_lower(b); e4=cam_upper(b)
    if l3!=e3 or l4!=e4:
        return ('MISMATCH',(l3,e3,l4,e4))
    return ('OK',None)
