package M;
use strict; use warnings;
our $EXE='/workspace/dataset/test20_executable';

sub toup { my $b=shift; return ($b>=0x61 && $b<=0x7a) ? $b-32 : $b; }

sub cam_lower {
  my @in = unpack('C*', shift);
  my @out; my $cap=0;
  for my $c (@in) {
    if ($c==0x5f) { $cap=1 }
    elsif ($cap) { push @out, toup($c); $cap=0 }
    else { push @out, $c }
  }
  return pack('C*', @out);
}
sub cam_upper {
  my @o = unpack('C*', cam_lower(shift));
  $o[0]=toup($o[0]) if @o;
  return pack('C*', @o);
}
# returns (status, l3, l4, raw)
sub run {
  my $s=shift;
  my $tmp="/tmp/adv/out.bin";
  my $pid = open(my $fh, '-|');
  die "fork" unless defined $pid;
  if ($pid==0) { open(STDERR,'>','/dev/null'); exec($EXE,$s) or exit 127; }
  local $/; my $raw = <$fh>; $raw='' unless defined $raw;
  close($fh); my $rc=$?;
  return ('ABORT',undef,undef,$raw,$rc) if $rc!=0;
  my @lines = split(/\n/, $raw, -1);
  return ('LINES', \@lines, $rc, $raw);
}
sub check {
  my $s=shift;
  my ($st,@r)=run($s);
  return ('ABORT', $r[3]) if $st eq 'ABORT';
  my @lines = @{$r[0]};
  return ('NLINES', scalar(@lines), $r[2]) unless scalar(@lines)==21;
  my ($l3,$l4)=($lines[2],$lines[3]);
  my ($e3,$e4)=(cam_lower($s),cam_upper($s));
  if ($l3 ne $e3 || $l4 ne $e4) { return ('MISMATCH', $l3,$e3,$l4,$e4); }
  return ('OK');
}
sub hx { my $s=shift; return join('',map{sprintf('\x%02x',$_)} unpack('C*',$s)); }
1;
