use lib "/tmp/adv"; require "m.pl";
# newline-aware: logical line i reconstructed assuming lines 1..2 contain k newlines each
sub M::check_nl {
  my $s=shift;
  my ($st,@r)=M::run($s);
  return ('ABORT') if $st eq 'ABORT';
  my @p=@{$r[0]};
  my $k=($s=~tr/\n//);
  my ($e3,$e4)=(M::cam_lower($s),M::cam_upper($s));
  my $k3=($e3=~tr/\n//); my $k4=($e4=~tr/\n//);
  my $i=2*($k+1);
  return ('OOR') if $i+$k3+1+$k4 > $#p;
  my $l3=join("\n", @p[$i .. $i+$k3]);
  my $j=$i+$k3+1;
  my $l4=join("\n", @p[$j .. $j+$k4]);
  return ('MISMATCH',$l3,$e3,$l4,$e4) if $l3 ne $e3 || $l4 ne $e4;
  return ('OK');
}
1;
