fn ascii_toupper(b: u8) -> u8 {
    if b.is_ascii_lowercase() { b - 32 } else { b }
}

/// line 3: camelize(word) — default 2nd parameter (lower-camel)
pub fn camelize_lower(input: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    let mut cap = false;
    for &c in input {
        if c == b'_' {
            cap = true;
        } else if cap {
            out.push(ascii_toupper(c)); // any byte consumes the flag
            cap = false;
        } else {
            out.push(c);
        }
    }
    out
}

// Convenience wrapper: bytes >= 0x80 are passed through untouched, so any UTF-8
// present in the input is still byte-identical (though a lone lead byte after '_'
// is NOT case-mapped — the transform is byte-based, not char-based).
pub fn camelize_lower_str(input: &str) -> String {
    unsafe { String::from_utf8_unchecked(camelize_lower(input.as_bytes())) }
}

/// line 4: camelize(word, false) — upper-camel / PascalCase
pub fn camelize_upper(input: &[u8]) -> Vec<u8> {
    let mut out = camelize_lower(input);
    if let Some(first) = out.first_mut() {
        *first = ascii_toupper(*first);   // first BYTE only; no-op if not b'a'..=b'z'
    }
    out
}

pub fn camelize_upper_str(input: &str) -> String {
    unsafe { String::from_utf8_unchecked(camelize_upper(input.as_bytes())) }
}
